  @Nested
  @DisplayName("simple style backward compatibility")
  class SimpleStyleTests {

    @Test
    @DisplayName("scalar returns stringified value")
    void scalarReturnsStringifiedValue() {
      assertEquals(
          "5", ValueSerializer.serializeStyled("id", "5", "path", "string", null, "simple", false));
    }

    @Test
    @DisplayName("array joins with comma")
    void arrayJoinsWithComma() {
      assertEquals(
          "3,4,5",
          ValueSerializer.serializeStyled(
              "id", Arrays.asList("3", "4", "5"), "path", "array", null, "simple", false));
    }

    @Test
    @DisplayName("null returns empty string")
    void nullReturnsEmptyString() {
      assertEquals(
          "", ValueSerializer.serializeStyled("id", null, "path", "string", null, "simple", true));
    }

    @Test
    @DisplayName("scalar URL-encodes path value")
    void scalarUrlEncodesPath() {
      // Path-location values are percent-encoded so reserved chars don't break the URL.
      assertEquals(
          "hello%20world",
          ValueSerializer.serializeStyled(
              "id", "hello world", "path", "string", null, "simple", false));
    }

    @Test
    @DisplayName("empty string path param throws IllegalArgumentException")
    void emptyStringPathParamThrows() {
      // Empty-string path values silently produce malformed URLs like
      // `/pet//details`; reject at serialization time so callers see
      // the real error rather than a downstream 404.
      assertThrows(
          IllegalArgumentException.class,
          () -> ValueSerializer.serializeStyled("id", "", "path", "string", null, "simple", false));
    }

    @Test
    @DisplayName("path value is encoded exactly once (no double-encoding)")
    void pathValueEncodedExactlyOnce() {
      // path-double-encoding: serializeStyled already percent-encodes the
      // path segment, so the api template must NOT wrap it again. A space
      // must become %20 (never %2520) and a slash %2F (never %252F).
      String space =
          String.valueOf(
              ValueSerializer.serializeStyled(
                  "id", "a b", "path", "string", null, "simple", false));
      assertEquals("a%20b", space);
      assertFalse(space.contains("%2520"));
      String slash =
          String.valueOf(
              ValueSerializer.serializeStyled(
                  "id", "a/b", "path", "string", null, "simple", false));
      assertEquals("a%2Fb", slash);
      assertFalse(slash.contains("%252F"));
    }
  }

